const normalize = (s) =>
  String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const cleanNewsTitle = (raw) => {
  const t = String(raw || '').replace(/\s+/g, ' ').trim();
  const idx = t.lastIndexOf(' - ');
  return idx > 25 ? t.slice(0, idx).trim() : t;
};

// 1. Collect existing titles in KigalContent to avoid duplicates
const existingTitles = new Set();
try {
  for (const item of $('Proyectos Actuales KigalContent').all()) {
    const j = item.json || {};
    if (j.working_title) existingTitles.add(normalize(j.working_title));
  }
} catch (_) {}

const isDuplicate = (titleNorm) => {
  if (!titleNorm || titleNorm.length < 12) return true;
  if (existingTitles.has(titleNorm)) return true;
  const words = new Set(titleNorm.split(' ').filter((w) => w.length > 4));
  for (const ex of existingTitles) {
    let overlap = 0;
    for (const w of words) {
      if (ex.includes(w)) overlap++;
    }
    if (words.size >= 3 && overlap >= Math.ceil(words.size * 0.65)) return true;
  }
  return false;
};

// 2. Niche relevance keywords (Kike Gallego: IA, automatizacion, pymes, ecommerce, web, digitalizacion)
const NICHE_KEYWORDS = [
  ['pyme', 4], ['pymes', 4], ['empresa', 3], ['negocio', 3], ['automatiz', 4],
  ['inteligencia artificial', 4], [' ia ', 3], ['agente', 3], ['agent', 3],
  ['claude', 3], ['openai', 2], ['gemini', 2], ['ollama', 4], ['n8n', 4],
  ['ecommerce', 4], ['e-commerce', 4], ['tienda online', 4], ['shopify', 3],
  ['seo', 3], ['marketing', 2], ['clientes', 3], ['ventas', 3], ['productividad', 3],
  ['digitalizacion', 4], ['transformacion digital', 4], ['workflow', 3], ['llm', 2]
];

const scoreCandidate = (title, snippet, isSpanish, bonusPoints = 0) => {
  const hay = ' ' + normalize(`${title} ${snippet}`) + ' ';
  let score = isSpanish ? 4 : 1;
  for (const [kw, pts] of NICHE_KEYWORDS) {
    if (hay.includes(kw)) score += pts;
  }
  score += Math.min(4, Math.floor(bonusPoints / 40));
  return score;
};

const candidates = [];
const seen = new Set();

const pushCandidate = (rawTitle, link, snippet, sourceLabel, isSpanish, bonusPoints = 0) => {
  const title = cleanNewsTitle(rawTitle);
  const norm = normalize(title);
  if (!title || seen.has(norm) || isDuplicate(norm)) return;
  seen.add(norm);
  const relevance = scoreCandidate(title, snippet, isSpanish, bonusPoints);
  candidates.push({
    title,
    link: String(link || '').trim(),
    snippet: String(snippet || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 360),
    sourceLabel,
    isSpanish,
    relevance,
  });
};

// 3. Gather Google News ES · IA & Pymes
try {
  for (const item of $('Google News ES · IA & Pymes').all().slice(0, 12)) {
    const j = item.json || {};
    if (j.title) {
      pushCandidate(j.title, j.link, j.contentSnippet || j.content || '', 'Google News ES · IA & Pymes', true);
    }
  }
} catch (_) {}

// 4. Gather Google News ES · E-commerce & Digitalización
try {
  for (const item of $('Google News ES · E-commerce & Digitalización').all().slice(0, 12)) {
    const j = item.json || {};
    if (j.title) {
      pushCandidate(j.title, j.link, j.contentSnippet || j.content || '', 'Google News ES · E-commerce & Digitalización', true);
    }
  }
} catch (_) {}

// 5. Gather Hacker News · IA & Automatización
try {
  for (const item of $('Hacker News · IA & Automatización').all()) {
    const hits = Array.isArray(item.json?.hits) ? item.json.hits : [];
    for (const h of hits.slice(0, 8)) {
      if (h.title) {
        const url = h.url || `https://news.ycombinator.com/item?id=${h.objectID}`;
        pushCandidate(h.title, url, `Tendencia tech en Hacker News (${h.points || 0} puntos, ${h.num_comments || 0} comentarios).`, 'Hacker News · Tech/IA', false, Number(h.points || 0));
      }
    }
  }
} catch (_) {}

candidates.sort((a, b) => b.relevance - a.relevance);

// Pick top 2 (at most 1 English HN item so Spanish business news always leads)
const picked = [];
let enCount = 0;
for (const c of candidates) {
  if (!c.isSpanish && enCount >= 1) continue;
  picked.push(c);
  if (!c.isSpanish) enCount++;
  if (picked.length >= 2) break;
}

return picked.map((c) => ({
  json: {
    concept_title: c.title.slice(0, 180),
    context_notes: `Radar Matutino (${c.sourceLabel}): ${c.snippet || c.title} | Enfoque para pymes españolas: traducir esta novedad en impacto práctico, ahorro de tiempo o captación de clientes. Fuente: ${c.link}`,
    source_origin: 'radar_matutino',
    source_url: c.link || 'https://news.google.com',
    target_platforms: ['LinkedIn', 'Instagram', 'YouTube'],
    target_duration: 'STANDARD_SHORT',
    conversion_goal: 'EMAIL_LEAD_CAPTURE',
    auto_evaluate_ai: true,
    auto_create_project: true,
  },
}));
